<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Domain\Marketing\MarketingPermission as P;
use App\Services\Marketing\MarketingContentTemplates as Templates;
use Illuminate\Http\Request;
class MarketingContentTemplatesController extends Controller {
 private function actor(Request $r,bool $edit=false):int {abort_unless(P::allows($r->user(),$edit?P::EDIT:P::VIEW),403);return $r->user()->id;}
 public function data(Request $r,Templates $s){$u=$this->actor($r);return response()->json(['templates'=>$s->listing($u),'accounts'=>$s->accounts(),'canEdit'=>P::allows($r->user(),P::EDIT),'canSubmit'=>(bool)$r->user()->is_super_admin&&config('marketing.whatsapp_template_submission_enabled',false),'storeName'=>app(\App\Support\ShopBrand::class)->name(),'campaigns'=>app(\App\Services\Marketing\MarketingCampaigns::class)->listing($u),'whatsappDrafts'=>app(\App\Services\Marketing\MarketingWhatsAppPreparation::class)->listing($u),'canCampaign'=>P::allows($r->user(),P::MANAGE_CAMPAIGNS),'csrf'=>csrf_token()])->header('Cache-Control','private, no-store');}
 public function index(Request $r){$this->actor($r);return response()->view('marketing.templates.index',['studioNavActive'=>'campaign-templates'])->header('Cache-Control','private, no-store');}
 public function save(Request $r,Templates $s,?string $id=null){$u=$this->actor($r,true);$d=$r->validate(['version'=>'required|integer|min:0','channel'=>'required|in:email,sms,whatsapp,post','name'=>'required|string|max:150','language'=>'required|in:en,en_US,en_GB,zh_CN,zh_HK,zh_TW,ms','account_id'=>'nullable|integer|min:1','body'=>'required|string|max:1024','meta_name'=>'sometimes|string|max:150','category'=>'sometimes|in:MARKETING,UTILITY','header_type'=>'sometimes|in:NONE,TEXT','header_text'=>'nullable|string|max:60','header_examples'=>'sometimes|array|max:1','header_examples.*'=>'nullable|string|max:200','buttons'=>'sometimes|array|max:3','buttons.*.type'=>'required|in:URL,PHONE_NUMBER,QUICK_REPLY','buttons.*.text'=>'required|string|max:25','buttons.*.value'=>'nullable|string|max:2000','buttons.*.example'=>'nullable|string|max:200','subject'=>'nullable|string|max:200','footer'=>'nullable|string|max:60','button'=>'nullable|string|max:25','url'=>'nullable|string|max:2000','examples'=>'sometimes|array|max:20','examples.*'=>'nullable|string|max:200','format'=>'required|in:image,carousel,video','assets'=>'sometimes|array|max:10','assets.*'=>'string|max:100|distinct']);foreach(['subject','footer','button','url'] as $key)$d[$key]=$d[$key]??'';return response()->json(['template'=>$s->save($u,$d,$id)],$id?200:201)->header('Cache-Control','no-store');}
 public function action(Request $r,Templates $s,string $id,string $action){$u=$this->actor($r,true);if(in_array($action,['submit','sync'],true))abort_unless($r->user()->is_super_admin,403);$d=$r->validate(['version'=>'required|integer|min:1']);$result=match($action){'submit'=>$s->submit($u,$id,$d['version']),'sync'=>$s->sync($u,$id,$d['version']),'duplicate'=>$s->duplicate($u,$id,$d['version']),'archive'=>$s->archive($u,$id,$d['version']),'restore'=>$s->archive($u,$id,$d['version'],true),'use-post'=>$s->usePost($u,$id),default=>abort(404)};return response()->json([$action==='use-post'?'post':'template'=>$result])->header('Cache-Control','no-store');}

 public function messageDraft(Request $r,\App\Services\Marketing\MarketingWhatsAppPreparation $s,?string $id=null){$u=$this->actor($r,true);abort_unless(P::allows($r->user(),P::MANAGE_CAMPAIGNS),403);$d=$r->validate(['version'=>'required|integer|min:0','campaign_id'=>'required|uuid','template_id'=>'required|uuid','values'=>'present|array|max:20','values.*'=>'required|string|max:200','timezone'=>'required|timezone','scheduled_for'=>'nullable|date']);return response()->json(['draft'=>$s->save($u,$d,$id)],$id?200:201)->header('Cache-Control','no-store');}
 public function messageReview(Request $r,\App\Services\Marketing\MarketingWhatsAppPreparation $s,string $id){return response()->json($s->review($this->actor($r),$id))->header('Cache-Control','private, no-store');}
}
